  });
  const wss = new WebSocketServer({ noServer: true, path: '/ws' });
  server.on('upgrade', (req, socket, head) => {
    if (req.url?.split('?')[0] === '/ws') wss.handleUpgrade(req, socket, head, client => wss.emit('connection', client));
