                {v === null ? "--" : v.toFixed(k.digits)}
              </span>
              <span className="truncate text-[13px] text-muted">{k.unit}</span>
            </div>
            <div className="mt-3 text-xs tabular">
              <Delta
                diff={v === null || p === null || p === undefined ? null : v - p}
